"""Build the signal map and its lock file."""

from __future__ import annotations

import difflib
from collections import defaultdict
from pathlib import Path

from django.conf import settings

from .conf import get_config
from .inspection import LiveReceiver, is_mapped, iter_live_receivers, load_urlconf
from .on_commit import is_on_commit

LOCK_HEADER = """\
# signals.lock: generated by `python manage.py signal_map --write`.
# Each line is a receiver: signal | sender | receiver [| uid=dispatch_uid].
# `signal_map --check` fails when this file is out of date, so new or removed
# receivers show up in code review. Regenerate it; do not edit it by hand.
"""


def collect(include_all: bool = False) -> list[LiveReceiver]:
    load_urlconf()
    items = [i for i in iter_live_receivers() if include_all or is_mapped(i)]
    return sorted(items, key=lambda i: (not i.first_party, i.lock_line))


def lock_text(items: list[LiveReceiver]) -> str:
    sections = [
        ("[first-party]", [i.lock_line for i in items if i.first_party]),
        ("[third-party]", [i.lock_line for i in items if not i.first_party]),
    ]
    parts = [LOCK_HEADER]
    for title, lines in sections:
        parts.append(f"\n{title}\n")
        parts.extend(f"{line}\n" for line in sorted(lines))
    return "".join(parts)


def readable_text(items: list[LiveReceiver], include_all: bool = False) -> str:
    third_party_title = (
        "Third-party receivers"
        if include_all
        else "Third-party receivers on your models"
    )
    out: list[str] = []
    for title, first_party in (
        ("First-party receivers", True),
        (third_party_title, False),
    ):
        group = [i for i in items if i.first_party is first_party]
        out.append(f"{title} ({len(group)})")
        if not group:
            out.append("  none")
        tree: dict[str, dict[str, list[LiveReceiver]]] = defaultdict(
            lambda: defaultdict(list)
        )
        for item in group:
            tree[item.signal_name][item.sender_label].append(item)
        for signal_name in sorted(tree):
            out.append(f"  {signal_name}")
            for sender in sorted(tree[signal_name]):
                out.append(f"    {sender}")
                for item in sorted(tree[signal_name][sender], key=lambda i: i.path):
                    extras = []
                    if item.location:
                        extras.append(item.location)
                    if item.dispatch_uid:
                        extras.append(f"uid={item.dispatch_uid}")
                    if is_on_commit(item.receiver):
                        extras.append("on commit")
                    suffix = f"  ({', '.join(extras)})" if extras else ""
                    out.append(f"      {item.path}{suffix}")
        out.append("")
    return "\n".join(out)


def lock_path(override: str | None = None) -> Path:
    path = Path(override or get_config().lock_file)
    if not path.is_absolute():
        base = getattr(settings, "BASE_DIR", None)
        path = Path(base) / path if base else Path.cwd() / path
    return path


def diff(expected: str, actual: str, path: Path) -> str:
    return "".join(
        difflib.unified_diff(
            actual.splitlines(keepends=True),
            expected.splitlines(keepends=True),
            fromfile=f"{path.name} (committed)",
            tofile=f"{path.name} (current code)",
        )
    )
